public class DiskHealthCheck : IHealthCheck
{
    public Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext ctx, CancellationToken ct = default)
        => Task.FromResult(HealthCheckResult.Healthy());
}

app.MapHealthChecks("/health", new HealthCheckOptions
{
    ResponseWriter = async (ctx, report) =>
    {
        ctx.Response.ContentType = "application/json";
        await ctx.Response.WriteAsJsonAsync(new { status = report.Status.ToString() });
    }
});

public class WeatherClient
{
    private readonly HttpClient _http;
    public WeatherClient(HttpClient http) => _http = http;
    public Task<string> GetAsync() => _http.GetStringAsync("/weather");
}

builder.Services.AddHttpClient("inventory")
    .AddResilienceHandler("inventory", b =>
    {
        b.AddRetry(new HttpRetryStrategyOptions
        {
            MaxRetryAttempts = 3,
            BackoffType = DelayBackoffType.Exponential,
            UseJitter = true
        });
        b.AddCircuitBreaker(new HttpCircuitBreakerStrategyOptions());
